// Quality evaluation stories for the Prompt API (`LanguageModel`).
//
// Each story runs a fixed, seeded subset of a public benchmark through the
// on-device model and reports a quality score next to prompt latency:
//
//   mmlu         MMLU, 0-shot multiple choice   -> accuracyScore
//   vizwiz       VizWiz-VQA (image + question)  -> accuracyScore
//   librispeech  LibriSpeech test-clean         -> wordErrorRate
//
// Datasets live in `public/blink-ai/dataset/` and are generated by
// `tools/blink-ai/prepare_quality_datasets.py`. Pass `?qualityLimit=N` to
// evaluate only the first N examples of each dataset (for smoke tests).

import { setProgress, updateUI } from '../runner.js';
import {
  MMLU_CHOICES,
  corpusWordErrorRate,
  extractShortAnswer,
  mean,
  parseMultipleChoice,
  transcriptErrors,
  vqaAccuracy,
} from './quality_metrics.js';

const DATA_BASE_URL = new URL('../../dataset/', import.meta.url);

// Request greedy decoding; Chrome maps 'most-predictable' to temperature 0 and
// topK 1. Chrome only honors samplingMode when the AIPromptAPIParams Blink
// feature is enabled, so by default sampling is not greedy and scores vary
// slightly between runs. (The `temperature` and `topK` options are deprecated
// and ignored on web pages.)
const GREEDY_SAMPLING = Object.freeze({ samplingMode: 'most-predictable' });
const TEXT_CREATE_OPTIONS = Object.freeze({
  ...GREEDY_SAMPLING,
  expectedInputs: [{ type: 'text', languages: ['en'] }],
  expectedOutputs: [{ type: 'text', languages: ['en'] }],
});
const IMAGE_CREATE_OPTIONS = Object.freeze({
  ...GREEDY_SAMPLING,
  expectedInputs: [{ type: 'text', languages: ['en'] }, { type: 'image' }],
  expectedOutputs: [{ type: 'text', languages: ['en'] }],
});
const AUDIO_CREATE_OPTIONS = Object.freeze({
  ...GREEDY_SAMPLING,
  expectedInputs: [{ type: 'text', languages: ['en'] }, { type: 'audio' }],
  expectedOutputs: [{ type: 'text', languages: ['en'] }],
});

const MMLU_PROMPT_OPTIONS = Object.freeze({
  responseConstraint: { type: 'string', enum: MMLU_CHOICES },
});
const DEFAULT_PROMPT_OPTIONS = Object.freeze({});

function qualityLimit() {
  const value = new URLSearchParams(window.location.search).get('qualityLimit');
  const limit = Number.parseInt(value ?? '');
  return limit > 0 ? limit : Infinity;
}

async function loadJsonl(fileName) {
  const response = await fetchAsset(fileName);
  const examples = (await response.text())
    .split('\n')
    .filter(line => line.trim())
    .map(line => JSON.parse(line));
  return examples.slice(0, qualityLimit());
}

async function fetchAsset(path) {
  const response = await fetch(new URL(path, DATA_BASE_URL));
  if (!response.ok) {
    throw new Error(`Failed to load ${path}: HTTP ${response.status}`);
  }
  return response;
}

// --- Dataset definitions ---

function buildMmluPrompt(example) {
  const subject = example.subject.replaceAll('_', ' ');
  const choices = example.choices
    .map((choice, i) => `${MMLU_CHOICES[i]}. ${choice}`)
    .join('\n');
  return `The following is a multiple choice question about ${subject}. ` +
    'Answer with only the letter (A, B, C, or D) of the correct choice.\n\n' +
    `${example.question}\n${choices}\nAnswer:`;
}

const MMLU = Object.freeze({
  file: 'mmlu/test.jsonl',
  createOptions: TEXT_CREATE_OPTIONS,
  promptOptions: MMLU_PROMPT_OPTIONS,
  buildPrompt: buildMmluPrompt,
  scoreExample: (example, response) => {
    const prediction = parseMultipleChoice(response);
    return { prediction, correct: prediction === example.answer ? 1 : 0 };
  },
  summarize: (scores) => ({
    accuracyScore: mean(scores.map(s => s.correct)),
    numUnparsed: scores.filter(s => s.prediction === null).length,
  }),
  headline: (metrics) => ({
    value: `${(metrics.accuracyScore * 100).toFixed(1)}%`,
    label: 'accuracy',
  }),
});

const VIZWIZ = Object.freeze({
  file: 'vizwiz/val.jsonl',
  createOptions: IMAGE_CREATE_OPTIONS,
  promptOptions: DEFAULT_PROMPT_OPTIONS,
  buildPrompt: async (example) => {
    const image = await (await fetchAsset(example.image)).blob();
    return [{
      role: 'user',
      content: [
        { type: 'image', value: image },
        {
          type: 'text',
          value: `${example.question}\n` +
            'Answer the question using a single word or phrase.',
        },
      ],
    }];
  },
  scoreExample: (example, response) => {
    const prediction = extractShortAnswer(response);
    return { prediction, accuracy: vqaAccuracy(prediction, example.answers) };
  },
  summarize: (scores) => ({
    accuracyScore: mean(scores.map(s => s.accuracy)),
  }),
  headline: (metrics) => ({
    value: `${(metrics.accuracyScore * 100).toFixed(1)}%`,
    label: 'VQA accuracy',
  }),
});

const LIBRISPEECH = Object.freeze({
  file: 'librispeech_test_clean/test_clean.jsonl',
  createOptions: AUDIO_CREATE_OPTIONS,
  promptOptions: DEFAULT_PROMPT_OPTIONS,
  buildPrompt: async (example) => {
    const audio = await (await fetchAsset(example.audio)).arrayBuffer();
    return [{
      role: 'user',
      content: [
        {
          type: 'text',
          value: 'Transcribe this English audio verbatim. Output only the ' +
            'transcription, without any commentary.',
        },
        { type: 'audio', value: audio },
      ],
    }];
  },
  scoreExample: (example, response) => ({
    prediction: response,
    ...transcriptErrors(example.transcription, response),
  }),
  summarize: (scores) => ({
    wordErrorRate: corpusWordErrorRate(scores),
  }),
  headline: (metrics) => ({
    value: `${(metrics.wordErrorRate * 100).toFixed(1)}%`,
    label: 'WER',
  }),
});

// --- Story runner ---

function createQualityStory(key, name, dataset) {
  return Object.freeze({
    name,
    createOptions: dataset.createOptions,
    headline: dataset.headline,
    run: async () => {
      updateUI('running', `Loading ${name} dataset...`, '--', 'Loading');
      const examples = await loadJsonl(dataset.file);
      if (examples.length === 0) {
        throw new Error(`${name}: dataset ${dataset.file} is empty.`);
      }

      const baseSession = await LanguageModel.create(dataset.createOptions);

      const scores = [];
      const promptTimesMs = [];
      const details = [];
      let numErrors = 0;
      try {
        for (const [i, example] of examples.entries()) {
          updateUI(
            'running', `${name}: example ${i + 1}/${examples.length}`,
            `${i + 1}/${examples.length}`, 'Evaluating');
          setProgress((100 * i) / examples.length);

          let response = '';
          let error;
          // A fresh clone per example keeps examples independent.
          const session = await baseSession.clone();
          try {
            const prompt = await dataset.buildPrompt(example);
            const start = performance.now();
            response = await session.prompt(prompt, dataset.promptOptions);
            promptTimesMs.push(performance.now() - start);
          } catch (e) {
            // Count failures against the score instead of aborting the run.
            numErrors++;
            error = String(e);
            console.warn(`[${key}] ${example.id} failed:`, e);
          } finally {
            session.destroy();
          }
          const score = dataset.scoreExample(example, response);
          scores.push(score);
          details.push({ id: example.id, response, error, ...score });
        }
      } finally {
        baseSession.destroy();
      }
      setProgress(100);

      if (numErrors === examples.length) {
        throw new Error(`${name}: all ${numErrors} prompts failed.`);
      }
      console.log(`[${key}] per-example results: ${JSON.stringify(details)}`);

      return {
        ...dataset.summarize(scores),
        numErrors,
        meanPromptTimeMs: mean(promptTimesMs),
      };
    },
  });
}

const STORIES = Object.freeze({
  'mmlu': createQualityStory('mmlu', 'Quality: MMLU (Text)', MMLU),
  'vizwiz': createQualityStory('vizwiz', 'Quality: VizWiz-VQA (Image)', VIZWIZ),
  'librispeech': createQualityStory(
    'librispeech', 'Quality: LibriSpeech (Audio)', LIBRISPEECH),
});

// --- Results ---

function formatMetric(format, value) {
  if (format === 'ms') return `${Math.round(value)} ms`;
  if (format === 'percent') return `${(value * 100).toFixed(1)}%`;
  return String(value);
}

function createStoryCard(story, storyMetrics) {
  const template = document.getElementById('quality-story-card-template');
  const card = template.content.cloneNode(true);
  const { value, label } = story.headline(storyMetrics);
  card.querySelector('.story-name').textContent = story.name;
  card.querySelector('.story-badge').textContent = `${value} ${label}`;
  for (const row of card.querySelectorAll('[data-metric]')) {
    const metricValue = storyMetrics[row.dataset.metric];
    if (metricValue === undefined) {
      row.remove();
      continue;
    }
    row.querySelector('.result-value').textContent =
      formatMetric(row.dataset.format, metricValue);
  }
  return card;
}

// The gauge shows mean accuracy across stories, using max(0, 1 - WER) for
// transcription stories.
function summarize(results) {
  const scores = Object.values(results).map(
    storyMetrics =>
      storyMetrics.accuracyScore ?? Math.max(0, 1 - storyMetrics.wordErrorRate),
  );
  return { value: `${(mean(scores) * 100).toFixed(1)}%`, label: 'accuracy' };
}

export const API_CONFIG = Object.freeze({
  name: 'language_model_quality',
  label: 'LanguageModel Quality',
  // Quality stories measure answer accuracy rather than cold-start latency, so
  // waiting out the 10s model idle timeout between stories is unnecessary.
  needsOffload: false,
  defaultStories: Object.freeze(Object.keys(STORIES)),
  stories: STORIES,
  isSupported: () => typeof LanguageModel !== 'undefined',
  availability: (options) => LanguageModel.availability(options),
  createSession: (options) => LanguageModel.create(options),
  createStoryCard,
  summarize,
});
